const { vec } = NMath;
const size = 28 * 28;
const targetCount = 300;

const samples = await IO.loadMNIST();
const randomImage = () => Float32Array.from({ length: size }, () => Math.random());

// Target digits: the plan and the transport both live in raw pixel space.
const digits = [...samples].sort(() => Math.random() - 0.5).slice(0, targetCount);
const pixelTargets = digits.map(digit => vec(...digit));

let ot;
let time = 0;
const image = IO.paintMNIST(new Float32Array(size));
const showTime = () => {
    if (!ot) return;
    // Source 0 is the user image; the noise images share the target mass with it.
    const [moved] = ot.interpolate(time, { indices: [0] });
    const pixels = moved.toArray();
    image.update(Float32Array.from(pixels, value => Math.max(0, Math.min(1, value))));
};

const drawing = IO.drawMNIST({
    randomButton: true,
    onSubmit: data => {
        const noise = Array.from({ length: targetCount - 1 }, randomImage);
        const images = [data, ...noise];
        ot = OptimalTransport.new(
            { points: images.map(img => vec(...img)) },
            { points: pixelTargets },
            { entropy: 0.005 },
        ).fit();
        console.log(`Sinkhorn iterations: ${ot.iterations}, transport cost: ${ot.cost().toFixed(4)}`);
        showTime();
    },
});

const ui = IO.UI(
    { type: "canvas", value: () => drawing },
    { type: "canvas", value: () => image },
    {
        type: "slider", value: () => ({
            title: "t:", min: 0, max: 1, step: 0.01, value: 0,
            onChange: value => { time = value; showTime(); },
        })
    },
);
ui;
